#!/usr/bin/env python3
"""Generate third_party/tok_unicode_nfc.h (Unicode NFC tables) from Python's unicodedata.

    python3 -I tests/fixtures/tok/gen_nfc.py > third_party/tok_unicode_nfc.h

Tables: canonical combining classes (ranges), full canonical decompositions of every code
point that has one (Hangul syllables excluded: they are algorithmic), and the primary
composition pairs (first, second) -> composite, excluding composition exclusions and
singletons. Pairs are validated against unicodedata.normalize("NFC", ...)."""
import sys
import unicodedata as ud

ver = ud.unidata_version
HANGUL = range(0xAC00, 0xD7A4)

ccc = []
for cp in range(0x110000):
    c = ud.combining(chr(cp))
    if c:
        if ccc and ccc[-1][1] == cp - 1 and ccc[-1][2] == c:
            ccc[-1][1] = cp
        else:
            ccc.append([cp, cp, c])

dec = []  # (cp, [full decomposition])
pool = []
for cp in range(0x110000):
    if cp in HANGUL or 0xD800 <= cp < 0xE000:
        continue
    s = chr(cp)
    d = ud.normalize("NFD", s)
    if d != s:
        dec.append((cp, len(pool), len(d)))
        pool.extend(ord(x) for x in d)

comp = []
for cp in range(0x110000):
    if cp in HANGUL or 0xD800 <= cp < 0xE000:
        continue
    d = ud.decomposition(chr(cp))
    if not d or d.startswith("<"):
        continue
    parts = d.split()
    if len(parts) != 2:
        continue
    a, b = int(parts[0], 16), int(parts[1], 16)
    if ud.normalize("NFC", chr(a) + chr(b)) == chr(cp):
        comp.append((a, b, cp))
comp.sort()

out = sys.stdout.write
out("/* GENERATED by tests/fixtures/tok/gen_nfc.py from Python unicodedata (Unicode %s), do not edit by hand.\n" % ver)
out(" * Unicode NFC data: combining classes, full canonical decompositions, primary composites. */\n")
out("#ifndef TOK_UNICODE_NFC_H\n#define TOK_UNICODE_NFC_H\n#include <stdint.h>\n\n")
out("#define NFC_UNICODE_VERSION \"%s\"\n\n" % ver)
out("static const uint32_t nfc_ccc[][3] = {\n")
for i in range(0, len(ccc), 4):
    out("    " + ",".join("{0x%X,0x%X,%d}" % tuple(x) for x in ccc[i:i + 4]) + ",\n")
out("};\nstatic const int nfc_ccc_n = %d;\n\n" % len(ccc))
out("static const uint32_t nfc_dec[][3] = { /* cp, offset into nfc_pool, length */\n")
for i in range(0, len(dec), 4):
    out("    " + ",".join("{0x%X,%d,%d}" % x for x in dec[i:i + 4]) + ",\n")
out("};\nstatic const int nfc_dec_n = %d;\n\n" % len(dec))
out("static const uint32_t nfc_pool[] = {\n")
for i in range(0, len(pool), 8):
    out("    " + ",".join("0x%X" % x for x in pool[i:i + 8]) + ",\n")
out("};\n\n")
out("static const uint32_t nfc_comp[][3] = { /* first, second, composite; sorted */\n")
for i in range(0, len(comp), 4):
    out("    " + ",".join("{0x%X,0x%X,0x%X}" % x for x in comp[i:i + 4]) + ",\n")
out("};\nstatic const int nfc_comp_n = %d;\n\n#endif\n" % len(comp))
